        }
        if fitting_bins_count > 0 && post_residual <= 4 {
            score += 120.0 * (1.0 - 0.4 * progress);
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 90.0 * (progress - 0.8) * 5.0;
        }
        if progress > 0.35 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0 * (progress - 0.35) * 3.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score += 55.0 * (1.0 - progress);
            }
        }
        if progress < 0.3 && item_size as f64 > cap * 0.7 && fitting_bins_count > 0 {
            score -= 25.0 * (0.3 - progress) * 10.0;
        }
        if progress > 0.25 && progress < 0.75 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            score += 35.0 * (1.0 - (progress - 0.25).abs() / 0.5);
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let new_res = cap - item_size as f64;
            if new_res > 0.0 && (next_item_size as f64) <= new_res {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if progress > 0.3 && progress < 0.9 && fitting_bins_count >= 2 && (mean_residual * 2.0) >= item_size as f64 {
            score += 55.0 * (1.0 - (progress - 0.3).abs() / 0.6).max(0.0);
        }
        let new_res2 = cap - item_size as f64;
        if fitting_bins_count > 0 && new_res2 > 0.0 && new_res2 < 10.0 {
            score += 90.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && new_res2 >= 10.0 && new_res2 < 16.0 && progress > 0.55 {
            score += 35.0 * (progress - 0.55);
        }
        if fitting_bins_count > 0 && next_item_size as f64 > cap * 0.5 && (cap - item_size as f64) < next_item_size as f64 {
            score += 30.0 * (0.5 + 0.5 * progress);
        }
        // MUTATION: residual-echo gate — resist opening a fresh bin whose
        // leftover far exceeds the typical residual of open bins.
        if fitting_bins_count > 0 && new_res2 > 0.0 {
            let echo = new_res2 - mean_residual;
            if echo > 0.0 {
                score += echo * 0.55 * (0.4 + 0.6 * progress);
            } else {
                score -= echo.min(cap * 0.25) * 0.4 * (1.0 - progress);
            }
        }
        // MUTATION: scarcity-aware opening — many open bins early, prefer consolidation.
        if fitting_bins_count > 0 && open_bins_count > 4 && progress < 0.6 {
            score += 12.0 * (open_bins_count.min(12) as f64 - 4.0) * (0.6 - progress);
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        if post_residual > 0 && post_residual <= 50 && (post_residual % 5 == 0) {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
        if progress > 0.4 && post_residual >= 15 && residual_f >= cap * 0.55 {
            score -= 20.0 * (progress - 0.4);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 90.0;
        }
        if post_residual > 0 && post_residual <= 6 {
            score -= 45.0 * (1.0 - post_residual as f64 / 7.0) * (0.6 + 0.8 * progress);
        }
        if next_item_size > 0 && (item_size as u64) + (next_item_size as u64) <= bin_residual as u64 {
            score -= 70.0 * (1.0 - 0.4 * progress);
        }
        // MUTATION: triple-fill anticipation — reward bins that could absorb
        // the next two items' worth of demand.
        if next_item_size > 0 && (item_size as u64) + 2 * (next_item_size as u64) <= bin_residual as u64 {
            score -= 30.0 * (1.0 - progress);
        }
        // MUTATION: harmonic residual targeting — reward mid reusable band
        // (25..45) when the next item is at most half the residual.
        if post_residual >= 25 && post_residual <= 45 && next_item_size > 0 && (next_item_size as u64) * 2 <= post_residual as u64 {
            score -= 26.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION: bin-closure race — escalate pressure to finish off
        // half-full bins when the placement nearly empties them.
        if post_residual > 0 && post_residual <= item_size && residual_f > cap * 0.4 {
            score -= 18.0 * (1.0 - post_residual as f64 / item_size.max(1) as f64) * (0.4 + 0.9 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly consumes the remainder
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits here later: reward closeness, penalize leftover after next
            let post2 = post_residual - next_item_size;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            score += post2 as f64 * 0.5;
        } else {
            // next item cannot use the remainder: penalize dead space
            score += gap * 0.35;
        }
    }

    // Penalize creating unusable slivers (dead space below min plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare against mean residual: prefer bins whose residual stays near the mean
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening fresh is attractive early or when many bins are open but fragmented
        if open_bins_count > 0 {
            score -= (open_bins_count as f64).ln() * 2.0;
        }
    }

    // Mild stream-progression pressure: later, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let post_frac = pr / cap;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = pr as f64;
    score += 20.0 * post_frac * post_frac * cap;

    // Perfect-fit bonus (smooth, no hard cutoff)
    let perfect = 1.0 - (post_frac * 4.0 - (post_frac * 4.0).round()).abs();
    score -= 15.0 * perfect * perfect;

    // Dead-space penalty: residuals too small for typical items
    let dead = (1.0 - post_frac).max(0.0) * (1.0 - (fit_frac + post_frac)).max(0.0);
    score += 10.0 * dead * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item can use the post residual
    if next_item_size > 0 {
        let next_fits = (pr - next_item_size as f64).max(0.0);
        let next_frac = next_fits / cap;
        score -= 12.0 * next_frac * (1.0 - progress);
        // Penalize if post residual is just barely too small for next item
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap <= 20.0 {
            score += 8.0 * (1.0 - gap / 20.0);
        }
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 5.0 - 10.0 * fragmentation.min(1.0) * progress;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    score -= 10.0 * progress * (1.0 - post_frac);

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: this item leaves exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // ideal chain: bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            // leftover after the next item would also fit; reward closeness
            let after_next = post_residual - next_item_size;
            score -= 200.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            score += 50.0 + (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: just minimize waste
        score -= 100.0;
    }

    // Tight fit now: small post_residual is good, but avoid tiny unusable slivers
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // sliver likely dead space
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with residuals below the mean (consolidate large holes)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Never prefer opening a new bin unless open bins are genuinely bad fits
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: new bin is correct
        }
    }

    score
}

