pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post; // best-fit base: oracle minimizes, so small leftovers win

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let urgency = 1.0 + 2.0 * progress;          // late in the stream, sealing bins matters more
    let frag = 1.0 + open_bins_count as f64 * 0.03; // fragmentation pressure
    let slack = (mean_residual / c).clamp(0.0, 1.0);

    // Harmonic class of the item: k = floor(C/s) copies fit per bin.
    let item_class = bin_capacity / item_size.max(1);

    // -- 1. Perfect seal: unconditionally the best outcome --
    if post_residual == 0 {
        score -= 20.0 + 10.0 * urgency;
        return score;
    }

    // -- 2. Near-seal: leftover bounded by C/25, waste is provably tiny --
    if post_residual <= bin_capacity / 25 {
        score -= 2.0 + 3.0 * urgency;
