        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= (5.0 + nxt * 0.15) * frag.min(2.0);
            if next_item_size == post_residual {
                score -= 4.0 + 4.0 * urgency; // exact two-item seal
            } else if post_residual % next_item_size == 0 {
                score -= 3.0; // leftover is an exact harmonic multiple of the next size
            }
        } else {
            // leftover is certainly useless for the immediate future
            score += (nxt - post).min(c) * 0.02;
        }
    }

    // -- 6. Capacity-grid alignment: leftovers on the C/4 lattice (25/50/75)
    //       are exactly fillable by common item combinations --
    let quarter = (bin_capacity / 4) as f64;
    let rem = post % quarter;
