        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are nearly full and few fitting options.
        let pressure = avg_fullness * 20.0 + (fitting_bins_count as f64).recip() * 5.0;
        score += 15.0 - pressure - progress * 5.0;
    }

    // Reward using bins that are already relatively full (high utilization).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Mild penalty for many open bins (encourage consolidation early).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual (minimize wasted space)
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize mid-range residuals more as stream progresses
    let bump = x * (1.0 - x); // peaks at x=0.5 (worst dead space)
    score += 40.0 * bump * (progress * progress + 0.2 * progress);

    // Reward tight fits increasingly over time
    score -= 25.0 * (1.0 - x) * (1.0 - x) * progress;

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: prefer bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 15.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Prefer fuller bins relative to mean residual
    score += (mean_residual - pr) * 0.3 * (0.5 + progress);

    // Slight penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is supreme.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into residue classes of capacity.
    // Residuals that form "usable" classes (>= smallest item 10, and divisible into common
    // chunk sizes 25/50) are less penalized than awkward odd remainders.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Awkward dead space: 0 < post_residual < 10 (cannot hold any item) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - frac);
    }

    // Modulo arithmetic: residuals congruent to 0 mod 25 or 0 mod 50 are "harmonic"
    // (they can be exactly filled by common item sizes) -> reward them.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0; // extra reward, stacked with the mod-25 bonus
    }
    // Odd residuals (post_residual % 2 == 1) can only be exactly filled by odd items;
    // mildly penalize to push toward even-partitioned bins.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Integer-division thresholds: how many minimum-size items (size 10) fit in post_residual.
    let slots = post_residual / 10;
    // Reward bins with many usable slots (flexibility), saturating at 5 slots (half capacity).
    let slots_f = (slots.min(5)) as f64;
    score -= 4.0 * slots_f;

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            // Harmonic bonus: post_residual - next_item_size lands on a friendly class.
            let rem = post_residual - next_item_size;
            if rem % 25 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item will NOT fit in this bin's leftover: the leftover becomes dead
            // unless another later item fits. Penalize proportionally.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it attractive
    // only when existing bins would create bad (sub-10 or very small) leftovers.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin: its post_residual equals capacity - item_size.
        // If the current best alternative would strand tiny dead space, the fresh bin
        // wins via the penalties above; otherwise keep fresh bin slightly discouraged.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 5.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, fresh bins are wasteful.
        score += 0.5 * (open_bins_count as f64).min(20.0);
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Mild preference for fuller bins as the stream progresses (reduce bin count early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post_residual is the core dead-space term.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill — actually perfect, reward it instead
        score -= 2000.0;
    } else if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: dead space that almost nothing can use.
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small gap: only tiny items can use it — moderate penalty.
        score += 12.0;
    }

    // Reward tight fits (small positive post_residual) beyond the linear base.
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64 + 1.0);
    }

    // Perfect fit bonus: filling a bin exactly frees it entirely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward; if the post residual is just barely too small for the next
    // item, penalize (we stranded a near-fit).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, avoid fragmenting residual
    // space further; encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.15 + 0.35 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's the "driest" bin — prefer draining it to keep mean residual high.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.1;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large relative to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin, adjusted by open-bin pressure.
        score = (bin_capacity - item_size) as f64;
        score += (open_bins_count as f64) * 1.2;
        // If item is large, a fresh bin is often the right call.
        if item_size >= 60 {
            score -= 15.0;
        }
        // If many bins can already fit the item, discourage a new bin.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // If next item fits in the post residual, mildly reward (keeps chain going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }

    // Dead space penalty: residual too small for any plausible future item
    // (items >= 1, but small slivers under ~10 are usually waste).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "nearly full" — prefer packing into them to close bins early.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave a large useful residual mismatch. New empty bin gets
    // post_residual = capacity - item_size, which is large; add a fixed
    // opening cost so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Mild preference early in the stream to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small to plausibly fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted lookahead opportunity.
            score += 3.0;
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance across bins),
    // but only when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count.min(50) as f64).sqrt();

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize existing bins slightly); late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for using a nearly-full bin when plenty of alternatives exist.
    if fitting_bins_count > 3 {
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight bias toward filling larger residual bins early (spread load).
    score += 0.02 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = pr * (1.0 + 2.0 * progress * (1.0 - x));

    // Smooth non-linear coupling: mid-range residuals are dead space, extreme residuals are fine.
    let mid = (x * (1.0 - x) * 4.0).powi(2); // peaks at x=0.5
    score += 12.0 * mid * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses.
    score -= (1.0 - x).powi(3) * 8.0 * progress;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = ((x - nx).abs()).max(0.0);
        score -= (1.0 - (fit * 4.0).min(1.0)) * 6.0 * (1.0 - progress);
    }

    // Slight penalty when bin residual deviates from mean residual (keep balance).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0 * progress;

    // Mild penalty for proliferation of open bins early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small post_residual (near-perfect fit) is heavily rewarded.
    let class = (post_residual % 10) as f64;
    score += class * 0.8; // penalize ragged residuals within a decade

    // Decade class of post_residual: integer division thresholds.
    let decade = post_residual / 10;
    score += match decade {
        0 => -12.0,          // 0-9: excellent fit
        1 => -6.0,           // 10-19
        2 => -2.0,           // 20-29
        3 => 2.0,            // 30-39
        4 => 5.0,            // 40-49
        5 => 8.0,            // 50-59
        6 => 11.0,           // 60-69
        7 => 14.0,           // 70-79
        8 => 17.0,           // 80-89
        _ => 20.0,           // 90+: nearly empty bin, wasteful placement
    };

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact harmonic match: post_residual is a perfect host.
            if post_residual == next_item_size {
                score -= 18.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                // Prefer chains where the leftover after next item is small.
                score -= 8.0 - (slack / cap) * 8.0;
            }
        } else {
            // Next item cannot follow: penalize, scaled by how close it was.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + (gap / cap) * 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 5 {
            score -= 6.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_residual - item_size;
    if is_new_bin {
        // Base penalty so a new bin loses to any reasonable existing fit.
        score += 22.0;
        // But if existing bins would leave huge dead space, prefer new bin:
        // compare this bin's waste against the mean residual landscape.
        if post_residual as f64 > mean_residual * 0.9 {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheap (flexibility for future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // If next item is large and this new bin would be nearly full, good.
        if next_item_size > 0 && post_residual < next_item_size && post_residual <= 15 {
            score -= 12.0;
        }
    }

    // Mild pressure against bin proliferation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Tight packing of large items: placing a big item snugly is valuable.
    if item_size >= 60 && post_residual <= 10 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10 typical) can use are pure waste.
    if post_residual > 0 {
        // Penalize small unusable gaps super-linearly; a gap of 1..9 is dead space.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 25.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling the bin deeply relative to its residual (tight packing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Mean residual coupling: if this bin is far below mean residual, it's already tight; prefer it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward leaving that gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Next item cannot use the leftover gap: penalize leaving a gap it can't use.
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, reduced by pressure to keep bins few.
        score = bin_capacity as f64 + open_bins_count as f64 * 2.0 - 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // this is an excellent chaining placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how tight the second fit is
            let second_residual = post_residual - next_item_size;
            score -= 150.0 * (1.0 - second_residual as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize bins that leave a gap
            // just barely too small for the next item (unusable dead space).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 120.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Compare residual against mean residual of open bins:
    // placing into a below-average-residual bin keeps big holes for future items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 400.0;
    }

    // Prefer filling bins with less residual relative to capacity (tightness).
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Early in the stream, be slightly more willing to open fresh bins
    // to build a good pool of partially-filled bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses (consolidate late),
        // but less when the best alternative would leave bad dead space.
        score += 50.0 + 150.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can always take the next item: mild bonus early on
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins early.
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 10.0;
        }
        // Perfect chaining: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 8.0;

    // Mean-residual coupling: penalize bins far above mean residual (outliers waste space)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be pickier about tight fits (more future items to serve)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: make empty bins slightly unattractive unless item is large
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (bigger leftover = worse fill)
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate wasted space; later, penalize dead space quadratically.
    let dead_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += dead_penalty;

    // Reward tight fits with a smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_kernel = (-diff * diff / (2.0 * 25.0)).exp();
        score -= 20.0 * fit_kernel * (0.4 + progress);
    }

    // Prefer bins whose residual is below mean residual (relatively full bins) via smooth term
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * (1.0 + progress);

    // Mild penalty for scattering across many open bins early on
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod 10 classes) ---
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals that are hard to fill (small, prime-ish gaps)
    if pr > 0 && pr < 10 {
        score += 25.0 - (pr as f64) * 2.0; // tiny gaps are worst
    }
    // Harmonic bonus for "nice" residuals divisible into common item sizes
    let nice = [0u32, 20, 25, 30, 40, 50, 60, 70, 75, 80, 90, 100];
    if nice.contains(&pr) {
        score -= 12.0;
    }
    // Modulo-10 residue class shaping: classes 0 and 5 are harmonically friendly
    match class {
        0 => score -= 6.0,
        5 => score -= 3.0,
        1 | 3 | 7 | 9 => score += 4.0,
        _ => {}
    }

    // --- Capacity fraction coupling ---
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac * frac) * 20.0; // penalize large wasted fraction quadratically

    // --- Integer division thresholds on next_item_size ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here too: strong reward, scaled by tightness
            let tight = (pr - next_item_size) as f64;
            score -= 15.0 + tight * 0.3;
            if (next_item_size % 10) == 0 {
                score -= 5.0; // round-size lookahead fits beautifully
            }
        } else {
            // next item cannot follow here; penalize more if gap is awkward
            let gap = pr;
            if gap > 0 && next_item_size - gap <= 10 {
                score += 8.0; // near-miss: bin becomes dead space
            }
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer new bin only when current item is large and existing residuals are poor
        let pressure = mean_residual / bin_capacity as f64;
        score = 60.0 - (item_size as f64) * 0.4 + pressure * 15.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0; // next item will need fresh space anyway
        }
    }

    // --- Stream progression: tighten late ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Mild penalty for bin proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

