pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 30.0 + 0.5 * leftover_after_next as f64;
        // Perfect chain: both items fill the bin exactly.
        if leftover_after_next == 0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving a large dead zone.
        score += 0.3 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when plenty of open bins exist and item is small.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.4 * item_size as f64;
        // But if the item is huge relative to mean residual, new bin may be better.
        if item_size as f64 > mean_residual {
            score -= 60.0;
        }
        // Few open bins early on: opening is cheap.
        if open_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 40.0 * (fit_ratio - 0.8) / 0.2;
    } else if fit_ratio < 0.3 {
        // Poor fit: penalize wasting a large bin on a small item.
        score += 15.0 * (0.3 - fit_ratio) / 0.3;
    }

    // Dead-space penalty: post_residual too small for any future item (min size 1,
    // but practically tiny leftovers are useless).
    if post_residual < 5 && post_residual > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is excellent; if next item almost fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        } else {
            score -= 5.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and load.
        score += 60.0;
        // Early in the stream, opening bins is cheaper (build a portfolio).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 25.0 * (1.0 - progress);
        // If many open bins are nearly full, a fresh bin is more valuable.
        score -= 10.0 * (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        // If the item is huge relative to typical residuals, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Global state: mildly prefer spreading load across bins when many are open
    // and mean residual is high (balance), but prefer consolidating when few bins.
    if open_bins_count > 0 {
        let balance_term = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        if open_bins_count > 4 {
            score += 5.0 * balance_term; // keep residuals similar when many bins open
        } else {
            score -= 5.0 * balance_term; // consolidate into emptier bins early
        }
    }

    // Time-horizon: late in the stream, be conservative — minimize waste hard.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream advances
    score -= (item_size as f64 / cap) * (1.0 + 2.0 * progress) * 6.0;

    // Penalize dead space relative to mean residual, smoothed non-linearly
    let dead = (norm_pr - mean_residual / cap).abs();
    score += 5.0 * dead * dead;

    // Lookahead coupling: prefer leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs() / cap;
        score -= 8.0 * fit_next * (1.0 - gap) * (0.5 + progress);
        score += 4.0 * (1.0 - fit_next) * (1.0 + progress);
    }

    // Last-chance bin bonus, decaying with progress
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for bin proliferation, non-linear in open bins
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 1.5;

    // New-bin candidate: smooth discouragement unless residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).tanh();
        score += 10.0 * (1.0 - frag) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "small" classes (< 10) are dead
    // space; leftovers in large classes are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Integer-division harmonic classes on post_residual (mod 25 buckets)
    let class = (post_residual / 25) as f64; // 0..4
    score -= class * 6.0; // larger leftover class => better bin

    // Penalize tiny dead space strongly (harmonic singularity near 0)
    if post_residual < 10 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Modulo arithmetic on item_size: classic harmonic classes (1/4, 1/2, 3/4 of capacity)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if item_size > half {
        score -= 15.0; // big item into a roomy bin is good
    } else if item_size >= quarter {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr < 10 {
                score -= 25.0; // chain leaves near-zero waste
            } else {
                score -= (npr as f64) / cap * 10.0;
            }
        } else {
            // next item won't fit here; slight penalty if this bin was its only option
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 20.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate handling: empty bin gets a mild handicap so existing
    // bins with decent fits win, but beats bins that would create dead space.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; scales down early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.75 - 10.0 * progress;
        // if no other bin fits, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // if next item is huge, a fresh bin is attractive
        if next_item_size > half {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: many open bins with high mean residual
    // suggests fragmentation; favor bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late-stream tightening: waste matters more as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.0 + progress * (pr / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
