        score += 150.0 * (1.0 - progress);
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin fits: opening is the only option.
            score -= 10000.0;
        } else {
            // Slight penalty so existing decent fits usually win, but relax
            // when item is large relative to mean residual or few bins open.
            score += 60.0;
            if item_size as f64 > mean_residual {
                score -= 70.0;
            }
            if open_bins_count <= 2 {
                score -= 40.0;
            }
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    // Slight late-stream tightening: waste matters more as stream progresses.
