}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect and near-perfect fits are supreme.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Awkward dead space: 0 < post_residual < 10 cannot hold any item.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 * (1.0 - progress);
    }

    // Harmonic residue classes: residuals divisible by 25/50 are exactly fillable.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Usable slots of minimum size (10): reward flexibility, saturating at 5 slots.
    let slots = (post_residual / 10).min(5) as f64;
    score -= 4.0 * slots;

    // Lookahead: chain the next item into this bin's leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let next_leftover = (post_residual - next_item_size) as f64;
            score -= 150.0 - next_leftover * 1.2;
            if (post_residual - next_item_size) % 25 == 0 {
                score -= 6.0;
            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Tightness vs. mean residual: prefer bins tighter than average now,
    // keeping loose bins available for larger future items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.6;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits at all,
    // or when every alternative leaves terrible dead space.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10000.0;
        } else {
            score += 60.0 + 0.5 * (open_bins_count as f64).min(20.0);
            if mean_residual > 40.0 {
                score += 10.0;
            }
        }
    }

    // Mild preference for fuller bins as the stream progresses.
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

