            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            // Dead space penalized more when the stream is early (more items remain
            // to suffer from wasted space) and when bins are already plentiful.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += dead * (2.0 + 2.5 * (1.0 - progress));
        }
    }

    // Penalize small unusable residuals below the minimum item size zone,
    // weighted by stream progression (dead space matters more early on).
    if post_residual > 0 && post_residual < 10 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 * (1.0 - progress);
    }

