    // Harmonic residue classes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Usable slots of minimum size (10): reward flexibility, saturating at 5.
    let slots = (post_residual / 10).min(5) as f64;
    score -= 4.0 * slots;

    // Aggressive 2-step lookahead: chain the next item into this bin's leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let next_leftover = (post_residual - next_item_size) as f64;
            if next_leftover <= 3.0 {
                score -= 260.0;
            } else {
                score -= 200.0 - next_leftover * 1.5;
            }
            if (post_residual - next_item_size) % 25 == 0 {
                score -= 6.0;
            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (2.0 + 2.5 * (1.0 - progress));
        }
    }

    // Tightness vs. mean residual: prefer tighter bins, keep loose ones for larger items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.8;
    } else {
        score += (residual_f - mean_residual) * 0.4;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin fits at all,
    // or when the item is large and the next item needs a fresh space.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10000.0;
