pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if pr < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
        } else if pr > 0 {
            score += 8.0; // residual too small for lookahead item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but keep it weak so a new empty bin can still win when fits are poor.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Mean residual context: prefer bins far below mean residual (consolidate waste).
    score += 0.3 * (mean_residual - pr as f64).abs() * 0.1;

    // Progress: slightly prefer filling existing bins later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

