    // have large mean residual (fragmented state) or many bins are open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        let crowding = (open_bins_count as f64 / (open_bins_count as f64 + 8.0));
        // Base cost of a fresh bin, discounted when fragmentation is high.
        score = 30.0 - 18.0 * fragmentation - 10.0 * crowding;
        // Reserve fresh bins for large items.
        score -= 0.25 * (item_size as f64);
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.6 {
