    if post_residual > 0 && post_residual < 8 && progress > 0.5 {
        score += 60.0 * (progress - 0.5) * 2.0;
    }

    // Coupling: reward bins whose residual closely matches the item.
    let match_gap = (bin_residual.saturating_sub(item_size)) as f64;
    if match_gap > 0.0 && match_gap < 6.0 {
        score -= (6.0 - match_gap) * 18.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 10000.0;
        } else if next_item_size > 0
            && next_item_size > post_residual
            && item_size >= bin_capacity / 2
            && open_bins_count >= 2
        {
            score -= 170.0;
        }
        // Late in the stream, opening a fresh bin is cheaper than fragmenting.
        if progress > 0.72 && fitting_bins_count > 0 && post_residual < item_size {
            score -= 70.0 * progress;
        }
        // Mid-stream: fresh bin keeps open bins tight for future items.
        if progress > 0.4 && progress <= 0.72 && item_size as f64 > mean_residual * 1.5 {
            score -= 40.0;
        }
        // Next item fits fresh capacity but not the post-fit residual.
        if next_item_size > 0
            && next_item_size > post_residual
            && next_item_size <= bin_capacity
            && fitting_bins_count <= 2
        {
            score -= 55.0 * (1.0 - progress);
        }
        // Prefer a new bin when the only fits are poor (large waste).
        if fitting_bins_count > 0 && waste_frac > 0.75 && item_size as f64 > mean_residual {
            score -= 50.0 * (1.0 - progress);
        }
        // Residual scarcity lookahead vs upcoming demand.
        if next_item_size > 0
            && open_bins_count > 0
            && (mean_residual * open_bins_count as f64) < (next_item_size as f64) * 1.2
        {
            score -= 45.0;
        }
        // Resist new bins when several poor fits exist but one is decent.
        if fitting_bins_count >= 3 && waste_frac > 0.65 {
            score -= 70.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // Resist new bins when mean residual across open bins could absorb item.
        if progress > 0.35 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0 * (progress - 0.35) * 3.0;
        }
        // Resist new bins when an open bin leaves a chain-compatible leftover.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score += 55.0 * (1.0 - progress);
            }
        }
        // Resist new bins when a near-exact fit exists among open bins.
        if fitting_bins_count > 0 && post_residual <= 4 {
            score += 120.0 * (1.0 - 0.4 * progress);
        }
        // Late-stream: strongly prefer closing out open bins.
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 90.0 * (progress - 0.8) * 5.0;
        }
    } else {
        // Mid-range residual: mild penalty when other fits exist.
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        // Reward consuming oversized residuals.
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are "nice"
    // (divisible into common item sizes) are more reusable than odd ones.
    let pr = post_residual;
    let mut harmony = 0.0f64;
