    } else {
        // divisibility rewards: leftover reusable by typical small items
        if pr % 10 == 0 { harmony -= 8.0; }
        if pr % 5 == 0 { harmony -= 3.0; }
        if pr % 20 == 0 { harmony -= 5.0; }
        if pr % 25 == 0 { harmony -= 4.0; }
        // dead-zone penalty: tiny unusable leftovers
        if pr < 10 { harmony += 30.0; }
        else if pr < 20 { harmony += 10.0; }
        // integer-division thresholds on capacity fractions
        let frac = (pr * 100) / bin_capacity; // 0..100 integer percent
        match frac / 10 { // decade class of leftover
            0 => harmony += 25.0,
            1 => harmony += 8.0,
            2 => harmony -= 2.0,
            3 => harmony -= 6.0,
            4 => harmony -= 9.0,
            5 => harmony -= 10.0,
            6 => harmony -= 9.0,
            7 => harmony -= 7.0,
            8 => harmony -= 4.0,
            _ => harmony -= 1.0,
        }
    }
    score += harmony;

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (or a harmonic multiple of it), reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 25.0;
