            score -= 12.0;
        } else if pr - next_item_size < 10 {
            score += 15.0; // next item would strand this bin
        } else {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Slight pressure to consolidate when many bins are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
        // prefer bins tighter than the mean residual (good fits)
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        // new-bin candidate: penalize mildly unless leftovers elsewhere are hopeless
        score += 12.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for a big upcoming item
        }
    }

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 6.0;
    }

    score
}

