    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves residual dead space; mild reward scaled by tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 50.0 * tightness;
        } else {
