pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space that nothing can use later
        let min_item = 1.0;
        if (post_residual as f64) < min_item {
            score += 20.0;
        }
        // Dead space penalty: small nonzero residuals are wasteful
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.5 * next_item_size as f64;
        } else {
            // residual too small for next item: penalize proportionally
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    } else {
        // Last item: just minimize post_residual strongly
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
