    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for proliferating bins early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.3;

    score
}

