            score -= 60.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals in (0,10) are nearly unusable (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic bands: residuals that are multiples of common item sizes
    // (10,20,25,50) are reusable; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leaving a gap that is dead space for the next item
            if gap < 10.0 {
                score += gap * 1.5;
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot fit here; slight reward for consuming big bin space
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // scaled by how full the stream is and how many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // but if the item is huge relative to mean residual, opening may be fine
        if mean_residual > 0.0 && (item_size as f64) > mean_residual * 0.9 {
            score -= 25.0;
        }
    }

    // Slight preference to fill emptier bins first when residuals are similar.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

