    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if lookahead fits almost perfectly.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= (10 - gap) as f64 * 1.5;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item.
        score += 4.0;
    }

