        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10 && item_size >= 50);
