    let mut score = post_residual as f64;

    // Reward tight fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, close the bin
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            // how well the next item would fit afterwards
            let two_step = post_residual - next_item_size;
            if two_step == 0 {
                score -= 300.0;
            } else if two_step < 10 {
                score -= 100.0;
            } else {
                // mild reward proportional to small leftover after two placements
                score -= (10.0 - two_step.min(10) as f64) * 2.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to the mismatch
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    }

    // Relative-to-mean-residual term: prefer bins that stay near the mean
    // (keeps residuals homogeneous, easier to combine future items).
    let diff = post_residual as f64 - mean_residual;
    score += (diff * diff) * 0.05;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // only open a new bin if all existing fits are bad (large post_residual)
            // and the next item is large enough to benefit from fresh space.
            let best_possible = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 0.0 };
            let _ = best_possible;
            score += 350.0;
            // Allow new bin if item is large and next item is also large (fresh space helps).
            if item_size >= 60 && next_item_size >= 60 {
                score -= 250.0;
            }
            // Late in the stream, avoid opening bins unless necessary.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 100.0;
        } else {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Slight preference for fuller bins (lower post_residual relative to capacity).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

