    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that is too small to hold the next item (wasted sliver),
    // but reward residuals that can accommodate the lookahead item.
