pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // early on, tolerate larger residuals (save big bins for later),
    // later on, penalize residual growth quadratically.
    let prog_coupling = 1.0 + 3.0 * progress * progress;
    score += pr * norm_pr * prog_coupling;

    // Smooth interaction: residual vs mean residual (prefer below-mean residuals)
    let mean_norm = mean_residual / cap;
    score += 4.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm) * (0.5 + progress);

    // Lookahead: reward if next item fits the resulting residual (smooth, not hard)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_slack = pr - nxt;
        if fit_slack >= 0.0 {
            score -= 8.0 * (1.0 - fit_slack / cap) * (1.0 + progress);
        } else {
            // penalize dead space that next item cannot use, smoothly
            score += 2.0 * (fit_slack.abs() / cap) * cap * 0.1;
        }
    }

    // Last-chance bin: smooth bonus to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Mild pressure against opening new bins when many are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual modulo 10 (dead-space granularity) ---
    let pr = post_residual as i64;
    let cls = (pr % 10) as f64;
    // Residuals in "harmonic" classes divisible by 10 (or close to 0) are reusable
    // by typical item sizes; odd fragments are dead space.
    if pr > 0 {
        let deadness = if pr < 10 {
            30.0 // tiny unusable fragment
        } else if cls <= 2.0 || cls >= 8.0 {
            -6.0 // near a round class, still reusable
        } else {
            (cls - 5.0).abs() * 1.5 // mid-fragment penalty
        };
        score += deadness;
    } else {
        score -= 40.0; // perfect fill
    }

    // --- Lookahead: does post_residual still fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how well the next item fits this leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / 10.0).min(8.0);
        } else {
            // leftover cannot host next item -> dead space risk
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // --- Last-chance bin: strongly prefer using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild preference for tighter competition (best-fit pressure)
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // --- New-bin candidate: keep it expensive unless all fits are poor ---
    if bin_residual == bin_capacity {
        score += 55.0;
        // cheaper to open a new bin late in the stream (less future to serve)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // but if the item is huge, a fresh bin is natural
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // --- Global pressure: many open bins -> prefer consolidation ---
    score += open_bins_count as f64 * 0.3;
    // deviation from mean residual: bins far from the mean are either
    // hoarders (good to fill) or nearly full (good to finish)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // --- Integer-division threshold coupling: item class vs residual class ---
    let item_class = item_size / 10;
    let resid_class = bin_residual / 10;
    if resid_class == item_class + 1 {
        score -= 8.0; // item lands in the top band of the bin: near-perfect fit
    }
    if post_residual < 10 && post_residual > 0 {
        score += 5.0; // sub-10 fragment almost never reusable
    }

    score
}

