    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Perfect chain fit: next item exactly fills the remaining space
        if diff == 0.0 {
            score -= 100.0;
        } else {
            // Reward tight chain fits, scaled by how much of next item fits
            let tightness = 1.0 - diff / bin_capacity as f64;
            score -= 40.0 * tightness * tightness;
        }
    } else if next_item_size > 0 {
        // Next item cannot chain into this bin: penalize proportionally to leftover waste
        score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Penalize post_residual that is dead space (too small for typical items 1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean coupling: prefer bins whose post_residual sits below mean residual
    // (consolidating space), reward bins tighter than the average open bin.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 10.0 * rel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive
    // only when the current bin would leave a bad fit. Penalize empty-bin selection
    // mildly so existing bins are preferred for good fits.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if next item is large and current fit is loose, empty bin becomes viable:
        if next_item_size > 0 && post_residual > next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference to fill earlier bins as stream progresses (stability)
    score += (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let waste_frac = 1.0 - post_residual as f64 / cap;
    let mut score = post_residual as f64;

    // Tiered rewards for exact/near-exact fits.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 320.0;
    } else if post_residual <= 6 {
        score -= 180.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= 16 {
        score -= 30.0;
    }

    // 2-step lookahead with chain-quality tiers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 2 {
                score -= 320.0;
            } else if leftover <= 5 {
                score -= 210.0;
            } else {
                score -= (200.0 - leftover as f64 * 1.6).max(35.0) * (1.2 - 0.4 * progress);
            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            let small_next = if next_item_size <= 25 { 1.35 } else { 1.0 };
            let scarcity = 1.0 + 0.15 * (open_bins_count.min(6) as f64).recip();
            score += dead * (2.0 + 2.8 * (1.0 - progress)) * small_next * scarcity;
        }
    }

    // Penalize small unusable residuals, weighted by stream progression.
    if post_residual > 0 && post_residual < 10 {
        let dead_boost = if next_item_size > post_residual { 1.4 } else { 1.0 };
        score += 190.0 * (1.0 - progress) * dead_boost;
    }

    // Mean-relative tightening with variance-aware asymmetric gains.
    let residual_f = bin_residual as f64;
    let var_gain = 0.85 + 0.6 * mean_residual / cap;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * var_gain;
    } else {
        score += (residual_f - mean_residual) * 0.5;
    }

    // Dead-space ratio and quadratic refinement.
    score += (1.0 - post_residual as f64 / cap) * 14.0 * progress;
    if waste_frac > 0.6 {
        score += (waste_frac - 0.6) * (90.0 + 40.0 * progress);
    }

    // Last-chance bonus: sole fitting bin strongly favored over a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Reusable sweet-spot residuals matched to upcoming demand.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr >= 20.0 && pr <= 60.0 {
            let reusable = if next_item_size > 0 && (next_item_size as f64) <= pr { 1.5 } else { 1.0 };
            score -= 22.0 * (1.0 - progress) * reusable;
        }
        if (pr - cap * 0.5).abs() < cap * 0.08 {
            score -= 40.0;
        }
    }

    // Keep tight bins for tight fits when alternatives exist.
    if bin_residual <= 12 && post_residual > 0 && fitting_bins_count > 1 && item_size < bin_residual {
        score += 55.0 * (1.0 - 0.5 * progress);
    }

    // Modular reuse of common small item sizes.
    if post_residual > 0 && post_residual <= 30 {
        let pr = post_residual as f64;
        let mod_bonus = if post_residual % 10 == 0 {
            60.0
        } else if post_residual % 5 == 0 {
            40.0
        } else {
            0.0
        };
        score -= mod_bonus * (0.6 + 0.4 * (1.0 - progress)) * (1.0 - pr / 60.0).max(0.5);
    }

    // Near-miss dead space penalty.
    if next_item_size > post_residual && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8.0 {
            score += (8.0 - gap) * 30.0 * (1.2 - progress);
        }
    }

    // Two-step chain bonus.
    if next_item_size > 0 && next_item_size < post_residual {
        let chain_left = post_residual - next_item_size;
        if chain_left >= 10 {
            score -= 45.0 * (1.0 - 0.5 * progress);
        }
    }

    // Late-stream consolidation: drain largest residuals to close bins.
    if progress > 0.85 && post_residual > 0 {
        let drain = (post_residual as f64 / cap) * (progress - 0.85) * 400.0;
        score -= drain;
    }

    // Slivers below 8 late in the stream are nearly always waste.
    if post_residual > 0 && post_residual < 8 && progress > 0.5 {
        score += 60.0 * (progress - 0.5) * 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 10000.0;
        } else if next_item_size > 0
            && next_item_size > post_residual
            && item_size >= bin_capacity / 2
            && open_bins_count >= 2
        {
            score -= 160.0;
        }
        if progress > 0.72 && fitting_bins_count > 0 && post_residual < item_size {
            score -= 60.0 * progress;
        }
        if progress > 0.4 && progress <= 0.72 && item_size as f64 > mean_residual * 1.5 {
            score -= 35.0;
        }
        if next_item_size > 0
            && next_item_size > post_residual
            && next_item_size <= bin_capacity
            && fitting_bins_count <= 2
        {
            score -= 50.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && waste_frac > 0.75 && item_size as f64 > mean_residual {
            score -= 45.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && waste_frac > 0.65 {
            score -= 70.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let near_fit_gap = (item_size as f64 - mean_residual).abs();
            if near_fit_gap < cap * 0.05 {
                score += 30.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count > 0 && post_residual <= 4 {
            score += 120.0 * (1.0 - 0.4 * progress);
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 90.0 * (progress - 0.8) * 5.0;
        }
        // Mid-stream, resist new bins when mean residual across open
        // bins could still absorb the item — reuse scattered space first.
        if progress > 0.35 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0 * (progress - 0.35) * 3.0;
        }
        // Resist new bins when the best post-residual among open bins
        // leaves a chain-compatible leftover (>= 10) for the next item.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score += 55.0 * (1.0 - progress);
            }
        }
        // Early stream, allow new bins for very large items that would
        // otherwise strand a small residual in an existing bin.
        if progress < 0.3 && item_size as f64 > cap * 0.7 && fitting_bins_count > 0 {
            score -= 25.0 * (0.3 - progress) * 10.0;
        }
        // MUTATION: opening a fresh bin wastes the full mean residual of every
        // other open bin; if the sum of usable residual space across open bins
        // (approximated by mean_residual * open_bins_count) is close to the
        // item, prefer to keep consolidating rather than fragment further.
        if fitting_bins_count > 0 && mean_residual > 0.0 {
            let total_usable = mean_residual * open_bins_count as f64;
            if total_usable >= item_size as f64 && total_usable < item_size as f64 * 2.0 {
                score += 55.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION: never open a new bin when an existing bin would end with a
        // residual that exactly matches the next item — that is a guaranteed
        // zero-waste chain and beats any fresh bin.
        if next_item_size > 0 && next_item_size == post_residual && post_residual > 0 {
            score += 400.0;
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream
        // so scattered space is consumed before fresh bins open.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when the
        // item is small and many bins fit it — keeps small residuals intact.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // MUTATION: residual-targeting bonus — reward placements whose
        // post_residual lands in the "likely next item" band around the
        // lookahead, scaled by how many bins still fit the item (competition).
        if post_residual > 0 && next_item_size > 0 {
            let pr = post_residual as f64;
            let nx = next_item_size as f64;
            let dist = (pr - nx).abs();
            if dist <= 4.0 {
                let comp = 1.0 / (fitting_bins_count.max(1) as f64);
                score -= (30.0 - dist * 5.0) * (0.7 + 0.6 * comp);
            }
        }
        // MUTATION: penalize leaving residuals in the "dead valley" band
        // (too big to waste but too small for typical mid-size items)
        // unless the next item actually fits — drives residuals toward
        // either near-zero or chain-compatible values.
        if post_residual >= 13 && post_residual <= 19 && next_item_size > post_residual {
            score += 35.0 * (1.0 - 0.5 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused: post_residual below
    // the minimum plausible item size (1) is fine, but small unusable gaps hurt.
    if post_residual > 0 {
        score += 6.0 / post_residual as f64;
    }

    // Lookahead: reward bins where the next item also fits in the leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward when the next item fills the post residual tightly.
            let next_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * next_fill;
        } else {
            // Next item won't fit here; slight penalty for creating awkward gap.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins to avoid sprawl.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 3.0 * pressure.min(10.0);

    // Time horizon: early in the stream, be pickier (larger penalty for loose fits);
    // late in the stream, just finish off bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.6 + 0.8 * progress;

    // Mean residual coupling: when mean residual is high, prefer bins below mean
    // residual (use up the fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

