    // Reward residuals that match common item size classes.
    let class_fit = |r: u32| -> f64 {
        // harmonic classes: multiples of 10 within item range
        let mut bonus = 0.0;
        for k in 1..=8 {
            let cls = 10 * k;
            if r == cls {
                bonus += 30.0;
            }
        }
        bonus
    };
    score -= class_fit(post_residual);

