    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving mid-range residue slightly
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer new bin when existing fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 250.0;
        // but if current bin choice would strand lots of space, new bin is fine
        if post_residual == bin_capacity {
            score -= 60.0 + 0.5 * mean_residual;
        }
