    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual,
    // this placement is a chain of two perfect fits — very desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits into post_residual, mildly reward keeping that option.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item will NOT fit here, the leftover gap is likely dead space;
    // penalize proportionally to how far off it is.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += ((next_item_size - post_residual) as f64) * 0.4;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bin count.
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits (this would be forced anyway), neutralize.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Last-chance pressure: if only one bin fits, avoid abandoning it.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    } else {
