            // next item fits but leaves a gap; mild reward scaled by fit quality.
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size <= post_residual + 10 && post_residual > 0 {
            // next item nearly fits: slight penalty for blocking a near miss.
            score += 8.0;
