    // into existing bins rather than opening new ones.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0;
        let gap = mean_residual - post_residual as f64;
        score -= gap * 0.3;
    }

    // Time horizon: early in the stream, be slightly more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
