        // in a fresh bin that is a poor match for the next item (dead space ahead).
        if fitting_bins_count > 0
            && next_item_size > 0
            && next_item_size > post_residual
            && post_residual > 0
        {
            score += 35.0 * (1.0 - progress) * (next_item_size - post_residual) as f64 / 50.0;
        }
