        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first for small items.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // MUTATION: reward closing bins — a perfect post-fit (residual 0) among
        // several candidates gets an extra nudge to fully consume scattered space.
        if post_residual == 0 && fitting_bins_count > 1 {
            score -= 80.0 * (0.5 + 0.5 * progress);
        }
        // MUTATION: gentle preference for bins whose post-residual stays
        // modular-friendly (multiple of 5) so future small items chain well.
        if post_residual > 0 && post_residual <= 40 && post_residual % 5 == 0 && next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10
    let post_class = (post_residual % 10) as f64;
    score += 0.8 * post_class;

    // Integer-division thresholds on post_residual: small leftovers are dead space
    let small_zone = post_residual / 10; // 0..=10 harmonic bucket
    match small_zone {
        0 => score += 12.0,               // nearly full: excellent
        1 => score += 4.0,
        2 => score += 0.0,
        3 => score -= 1.5,
        4 => score -= 3.0,
        5 => score -= 4.5,                // ~50% leftover: prime real estate
        6 => score -= 4.0,
        7 => score -= 2.5,
        8 => score -= 1.0,
        9 => score += 2.0,                // nearly empty: wasteful placement
        _ => score += 6.0,
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        let fits_next = next_item_size <= post_residual;
        if fits_next {
            let next_class = (next_item_size % 10) as f64;
            score -= 6.0 + 0.3 * next_class;
            // exact match of next item to post residual
            if next_item_size == post_residual {
                score -= 15.0;
            }
            // harmonic pairing: post_residual and next_item share residue class
            if post_residual % 10 == next_item_size % 10 {
                score -= 2.0;
            }
        } else {
            score += 3.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize so it's only chosen when open bins are hopeless
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 8.0; // big next item: fresh bin is attractive
        }
