        // open-bin residual is at least half the item — scattered space is
        // plentiful and should be consumed first.
        if item_size <= 30 && fitting_bins_count > 0 && mean_residual >= (item_size as f64) * 0.5 {
            score += 45.0 * (0.5 + 0.5 * (1.0 - progress));
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream
        // so scattered space is consumed before fresh bins open.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when the item is
        // small and many bins fit it — keeps small residuals intact.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // MUTATION: reward leaving residuals that exactly match the next item
        // even when the fit is loose — sets up a two-step perfect chain.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 6 {
                score -= (6 - slack) as f64 * 18.0;
            }
        }
        // MUTATION: gentle drain of mid-sized residuals late in the stream,
        // extended earlier (progress > 0.7) to close bins sooner.
        if progress > 0.7 && post_residual > 0 && post_residual < item_size {
            score += (item_size - post_residual) as f64 * 3.0 * (progress - 0.7);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

