}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum item size is worthless.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 1000.0; // perfect fill
    }

    // Penalize post_residual relative to capacity (fractional waste).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (chain fill).
    if next_item_size > 0 {
        let nj = next_item_size as f64;
        if (nj - post_residual as f64).abs() < 0.5 {
            score -= 40.0;
        } else if post_residual as f64 >= nj {
            score -= 8.0 * (1.0 - (post_residual as f64 - nj) / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0 * (nj - post_residual as f64).min(50.0) / 50.0;
        }
    } else {
        // last item: pure fill, reward any placement that uses an open bin
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it heavily
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins with high mean residual -> consolidate,
    // penalize spreading into fresh space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    score += 3.0 * consolidation * (0.5 + progress);

    // Early in the stream, allow some exploration of new bins when the fit is poor;
    // late in the stream, strongly prefer existing bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        60.0 * (1.0 - progress) + 30.0
    } else {
        0.0
    };
    score += new_bin_penalty;

    // Nonlinear tightness reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
