    let pr = post_residual;
    if pr > 0 {
        let reusable = pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0;
        if reusable {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Integer-division dead-space class: post_residual in (0,10) is nearly unusable
        // since items are >= 1 but often larger.
        if pr < 10 {
            score += 12.0;
        }
    }

    // Coupling with lookahead: if the next item fits exactly into post_residual,
    // this is a chained perfect fit — strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if pr >= next_item_size {
            // next item fits, but leaves its own residue; modulate by its class
            let nres = pr - next_item_size;
            if nres % 10 == 0 {
                score -= 15.0;
            } else if nres < 10 {
                score += 10.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty for tight packing
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it when the current fit leaves an awkward residue class and
    // other bins are plentiful; otherwise discourage spreading out.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 25.0 + 20.0 * (1.0 - progress);
        // discourage new bin when a decent fit exists elsewhere
        score += base;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // room for the pair in a fresh bin
            score -= 10.0;
        }
    }

    // Tightness bonus: reward filling a large fraction of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Deviation from mean residual: prefer bins with less residual (tighter bins)
    // when item is large, but leave roomier bins for small items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * (item_size as f64 / cap);

    // Threshold class on item size: big items should go into emptiest bins.
    if item_size > 50 {
        score += 3.0 * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
