    // Harmonic class of post_residual: perfect fits and "nice" residuals
    // (multiples of 10, or residuals that common items can still use) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Residual divisible by 10 -> aligns with grid-like item sizes, still very usable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Dead-space classes: residuals in (0, 10) are nearly unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Fraction-of-capacity harmonic thresholds: residual in [30, 60] is prime space
    // for medium items; penalize wasting it on tiny items.
    let frac = post / cap;
    if frac > 0.30 && frac <= 0.60 && item_size < 30 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic bonus: next item leaves a multiple-of-10 residual again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
