    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize dead space that no future item can plausibly fill.
    // Items are 1..=100; a residual smaller than the minimum plausible item is dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size + item_size {
            // next item would have fit had we not placed here; mild penalty
            score += 6.0;
        }
        // Exact chain fit: post residual exactly equals next item => perfect pairing
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
