    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // over the stream horizon and when no existing bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 20.0 + 25.0 * progress;
        // If few bins can fit, opening a new bin is less bad.
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        new_bin_cost += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
        score += new_bin_cost;
    }

    // Mild fragmentation penalty: post residual that is awkward (not a common item size)
    let awkward = ((post_residual as f64) / 10.0).fract();
    score += 8.0 * awkward;

    // Slight time-horizon adaptation: early in stream, be greedy about tight fits;
