    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 50 {
        score += 5.0;
    }

    // Dead-space penalty grows super-linearly for mid-range residuals.
    let frac = post_residual as f64 / cap;
    score += 20.0 * frac * frac;

    // Harmonic pairing: does next item fit exactly into post_residual?
