    // open bins are crowded (mean residual small).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 0.25 * cap;
        let big_item = item_size > 60;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.2;
        score += 35.0;
        if crowded { score -= 45.0; }
        if big_item { score -= 10.0; }
