    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Reward filling bins tightly when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline, slightly high so it's chosen only when open bins look bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If item is huge and no good fit expected, opening new bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
