    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: squashed post-residual
    let tight = 1.0 - (post / cap).powf(2.0);
    score -= 30.0 * tight * (item_size as f64 / cap);

    // Lookahead: bonus if next item fits into post-residual
