        score -= 12.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to wasted coupling
        score += 4.0 * (post / cap);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when open bins fit well,
    // but reward when current bin would leave awkward dead space
    if bin_residual == bin_capacity {
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count > 0 && mean_fit < 25.0 {
            score += 40.0; // existing bins fit fine, don't open new
        } else if post < 10.0 && post > 0.0 {
            score -= 5.0; // tiny dead space anyway
        } else {
            score += 8.0;
        }
