    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, small, or divisible into common item sizes) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if pr < 10 {
        score -= 18.0; // dead space below the minimum item size is acceptable
