        if best_fit == 0 {
            score += 25.0; // residual too small for any common class
        } else {
            let waste = pr - best_fit;
            score += waste as f64 * 0.9; // harmonic waste penalty
        }
        // modulo structure: residuals divisible by 10 are re-usable
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead: does the next item fit the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (next_item_size as f64) * 0.1;
        // extra reward if next item exactly fills the remaining space
        if next_item_size == pr {
            score -= 15.0;
        }
    } else if next_item_size > pr && pr > 0 {
        score += 5.0; // next item won't chain here; residual likely wasted
    }

