    // item is large or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // prefer new bin if item is big and existing residuals are poor fits
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.6 && fragmentation < 0.45 {
            score -= 12.0 * (item_frac - 0.6) * 10.0 * (0.5 + progress * 0.5);
