        }
        // MUTATION: strong resistance to new bins for small items when any
        // open bin's residual is at least item_size — small items should
        // almost never open fresh bins.
        if fitting_bins_count > 0 && item_size <= 15 {
            score += 140.0 * (1.0 - 0.5 * progress);
        }
        // MUTATION: resist new bins when the item fits the mean residual with
        // slack (mean-relative compaction pressure).
        if fitting_bins_count > 0 && item_size as f64 <= mean_residual * 0.9 {
            score += 55.0 * (0.5 + 0.5 * progress);
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
