        // item's own footprint class gets a compaction bonus.
        if post_residual > 0 && post_residual <= 2 {
            score -= 45.0 * (0.6 + 0.4 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1..=9] is nearly unusable
    // (item sizes >= 1, but small gaps rarely match future items) -> heavy penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Gaps in [10..=20] are risky too (only small items fit); moderate penalty.
    else if post_residual > 9 && post_residual <= 20 {
        score += 12.0 + (20 - post_residual) as f64 * 0.8;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tightness relative to bin capacity (fractional waste).
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more dead space -> mild penalty scaled by waste
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this gap: dead space likely permanent
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open,
    // implemented by rewarding use of existing bins as open_bins_count grows.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // New-bin candidate: penalize when open bins exist and mean residual
        // suggests they can still absorb items.
        score += 15.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.3;
