        // enough that leaving it out would strand proportionally more space;
        // otherwise strengthen the pull toward existing bins.
        if progress > 0.45 && progress < 0.8 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            score += 70.0 * (0.8 - progress);
        }
    } else {
