pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes (harmonic to the stream) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize tiny dead space (< 10): unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post) / 10.0;
    }
    // Reward exact fit strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo harmonic bonus: post_residual divisible by common granularities
    // (5, 10, 20, 25) leaves room for future items of standard sizes.
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if *m > 0 && r % m == 0 { h += 1.0; }
        }
        h
    };
    score -= 4.0 * harmonic(post_residual);

    // Fractional capacity thresholds: classify post_residual into quartiles.
    let frac = post / cap;
    if frac > 0.75 {
        score -= 6.0;   // nearly empty bin still: good target
    } else if frac < 0.05 && post_residual > 0 {
        score += 8.0;   // nearly full but not exact: dead zone
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * harmonic(post_residual - next_item_size);
            score += 0.5 * ((post_residual - next_item_size) as f64);
        } else {
            // next item cannot use this residual: slight penalty proportional to gap
            score += 0.3 * ((next_item_size - post_residual) as f64).min(20.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 10 && post_residual > 0 { score -= 5.0; }
    }

    // New-bin candidate handling: an empty bin has neutral attractiveness;
    // prefer it only when the stream is early or open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.35 * cap + 20.0 * progress - 2.0 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming, fresh bin useful
        }
