    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into eighths.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..8 harmonic class

    // Reward placements that leave residuals in "reusable" harmonic classes.
    // Class 0 (perfect fit) heavily rewarded; tiny residuals (dead space) penalized.
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,   // residual ~12.5: fits small items well
        2 => score -= 15.0,   // residual ~25: mid-small items
        3 => score += 5.0,    // awkward zone
        4 => score -= 10.0,   // residual ~50: half bin, very reusable
        5 => score += 8.0,
        6 => score -= 5.0,
        7 => score += 12.0,   // nearly full bin but wasted most of it
        _ => {}
    }

    // Dead-space penalty for very small post residuals (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post residual,
    // penalize if next item barely misses.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 55.0; // perfect chained fit
            } else if slack < 10.0 {
                score += 20.0; // creates sliver after next placement
            } else {
                score -= 10.0;
            }
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // When many bins are open, prefer tightening residual spread toward mean.
    let prog = step_index as f64 / total_items.max(1) as f64;
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * (0.15 + 0.2 * prog);

    // Prefer filling already-open bins over opening new ones, more so early on.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - prog);
    } else {
        score -= 5.0 * (1.0 - prog);
