    // Mild penalty for very loose fits (item much smaller than residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.3 {
        score += 12.0 * (0.3 - fill_ratio) * 10.0;
    }

    score
}

