    // how much of the bin is wasted overall.
    if next_item_size > post_residual && post_residual > 0 {
        let stranded = (next_item_size - post_residual) as f64;
        score += stranded * waste_frac * 18.0 * (0.4 + 0.6 * progress);
    }

    // Harvestable-residual matching: reward bins whose post-residual closely
    // matches the next item size (fine-grained residual + lookahead coupling).
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let n = next_item_size as f64;
        if (pr - n).abs() <= 2.0 {
            score -= 90.0 * (1.0 - 0.3 * progress);
        } else if (pr - n).abs() <= 5.0 {
            score -= 35.0 * (1.0 - 0.3 * progress);
