            if npost < 10 {
                score += 8.0; // creates a future dead gap
            } else {
                score -= 3.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening is fine.
    let progress = step_index as f64 / total_items.max(1) as f64;
