    score -= fill * fill * (10.0 + 20.0 * progress);

    // Penalize bins that deviate from mean residual (smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += (dev / cap) * (dev / cap) * 8.0;

    // Last-chance bonus: strongly favor the only bin that fits (smooth reward).
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space for the next item (smooth quadratic overlap).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        let overlap = (diff / cap).max(0.0);
        score -= overlap * overlap * 12.0;
        // Penalize if next item can't fit in post-residual (smooth penalty).
        if diff < 0.0 {
            score += (-diff / cap) * (-diff / cap) * 10.0;
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // New-bin candidate: make it slightly unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress - (mean_residual / cap) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
