        // leaves a small (<= 5) residual — near-perfect placement dominates.
        if fitting_bins_count > 0 && post_residual > 0 && post_residual <= 5 {
            score += 140.0 * (1.0 - 0.3 * progress);
        }
        // MUTATION: late-stream, opening a new bin is only justified if the
        // item is big enough that existing residuals cannot plausibly hold it
        // after a split; tighten the gate with open_bins_count pressure.
        if progress > 0.6 && fitting_bins_count > 0 && open_bins_count > 4 {
            score += 30.0 * (progress - 0.6) * (open_bins_count.min(12) as f64);
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        if post_residual > 0 && post_residual <= 50 && (post_residual % 5 == 0) {
            score -= 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
        // MUTATION: compaction pressure — prefer consuming the LARGEST
        // residuals first (drain scattered space), scaled by how many bins
        // fit the item (many fitting bins = plenty of placement freedom).
        if post_residual > 0 && fitting_bins_count > 1 {
            score -= (post_residual as f64 / cap) * 26.0 * (1.0 + 0.5 * (1.0 - progress));
        }
        // MUTATION: reward placements that leave a residual matching the
        // next item exactly even when not an exact bin fill (chain setup).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0 * (1.0 - 0.5 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: rewards residuals that fall into
    // "usable" size classes (multiples of common item granularities).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect closure is ideal
    } else if pr <= 10 {
        12.0 // tiny dead space is nearly unusable
    } else if pr % 10 == 0 {
        -8.0 // round residuals align with typical item sizes
    } else if pr % 5 == 0 {
        -4.0
    } else {
        3.0
    };
    score += class_bonus;

    // Integer-division thresholds: residual buckets by capacity fraction.
    let frac = pr as f64 / cap;
    if frac < 0.1 {
        score += 10.0; // dead space under 10% of capacity
    } else if frac < 0.3 {
        score += 4.0;
    } else if frac < 0.6 {
        score -= 3.0; // mid-range residual is flexible
    } else {
        score -= 6.0; // large residual keeps bin useful
    }

    // Lookahead coupling: penalize if next item cannot use post-residual.
    if next_item_size > 0 {
        if next_item_size > pr {
            score += 15.0; // next item forced elsewhere -> wasted space
        } else {
            let gap = pr - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / cap); // tight next-fit reward
            if gap == 0 {
                score -= 10.0; // next item closes bin exactly
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin would
    // leave a bad class of residual or open bins are already numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual * 0.3;
        score += 25.0 + pressure - 20.0 * progress;
        if post_residual == bin_capacity {
            // empty-bin call: post_residual equals capacity; keep neutral-ish
            score -= 10.0;
        }
    }

    // Mild congestion penalty: spreading items across too many bins is bad.
    score += 0.05 * open_bins_count as f64;

    // Mean-residual anchoring: prefer bins whose post-residual tracks the mean.
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

