    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize medium dead space that likely cannot fit future items
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 15.0;
    }

    // If the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; slight penalty for blocking lookahead
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open bins pressure: many open bins -> favor filling existing ones
    score += (open_bins_count as f64) * 0.8;

    // Compare against mean residual: bins with residual below mean are "tighter"
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral base; only attractive when open bins are scarce
    if bin_residual == bin_capacity {
        score += 10.0 - (open_bins_count as f64) * 0.9;
