        }
        // MUTATION: reward bins whose post-residual can host the next item
        // AND still leave a reusable >= 10 leftover (double-chain potential).
        if next_item_size > 0 && post_residual >= next_item_size + 10 {
            score -= 20.0 * (1.0 - 0.5 * progress);
        }
        // MUTATION: extra reward for consuming the largest residuals when
        // many bins fit — reduces residual variance across open bins.
        if fitting_bins_count > 2 && residual_f >= mean_residual * 1.8 {
            score -= 10.0 * (residual_f / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual,
    // penalize when next item cannot fit (dead space for the lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item can't use the leftover space: penalize proportional waste
            score += 30.0 + 0.5 * post_residual as f64;
        }
    }

    // Reward leaving large usable space, penalize tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when current item is small relative
    // to capacity (preserve open bins for big items) and many bins are open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 / 10.0;
        score = 150.0 + 200.0 * frac - 30.0 * pressure + 50.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // fresh bin can serve both items
        }
    }

    score
}

