pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction-of-capacity class of post_residual (capacity fractions).
    let frac = post / cap;
    // Penalize leftovers in awkward zones (just above small-item sizes).
    if frac > 0.0 && frac < 0.10 {
        score += 12.0 * (0.10 - frac); // nearly-full bin: tiny dead space, but reward closeness
    }
    if frac >= 0.10 && frac < 0.20 {
        score += 6.0; // dead zone: too big for nothing, too small for most
    }
    if frac >= 0.20 && frac < 0.35 {
        score -= 4.0; // sweet spot for medium items
    }
    if frac >= 0.35 && frac < 0.55 {
        score -= 2.0;
    }

    // Integer-division harmonic class: leftover divisible by small strides
    // (10, 20, 25) is more likely reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 5.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: does this bin's post_residual admit the next item exactly?
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 15.0; // perfect two-item closure
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 8.0; // next item keeps residue on a harmonic class
        } else {
            score -= 3.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 4.0; // next item won't fit here anyway
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when the item is large relative to capacity and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap - 0.35).abs();
        score = cap * 0.5 + 30.0 * fragmentation + 10.0 * progress;
        if item_size >= 70 { score -= 25.0; } // big items start fresh bins more readily
        if item_size <= 25 { score += 25.0; } // small items should fill existing space
    }

    // Mild global pressure: more open bins -> prefer consolidating into existing ones.
    score += 0.15 * open_bins_count as f64;

    // Mean-residual alignment: prefer bins near the mean (keeps the pool balanced).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let waste_frac = 1.0 - post_residual as f64 / cap;
    let mut score = post_residual as f64;

    // Tiered rewards for exact/near-exact fits.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 320.0;
    } else if post_residual <= 6 {
        score -= 180.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= 16 {
        score -= 30.0;
    }

    // 2-step lookahead with chain-quality tiers.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 2 {
                score -= 320.0;
            } else if leftover <= 5 {
                score -= 210.0;
            } else {
                score -= (200.0 - leftover as f64 * 1.6).max(35.0) * (1.2 - 0.4 * progress);
            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            let small_next = if next_item_size <= 25 { 1.35 } else { 1.0 };
            let scarcity = 1.0 + 0.15 * (open_bins_count.min(6) as f64).recip();
            score += dead * (2.0 + 2.8 * (1.0 - progress)) * small_next * scarcity;
        }
    }

    // Penalize small unusable residuals, weighted by stream progression.
    if post_residual > 0 && post_residual < 10 {
        let dead_boost = if next_item_size > post_residual { 1.4 } else { 1.0 };
        score += 190.0 * (1.0 - progress) * dead_boost;
    }

    // Mean-relative tightening with variance-aware asymmetric gains.
    let residual_f = bin_residual as f64;
    let var_gain = 0.85 + 0.6 * mean_residual / cap;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * var_gain;
    } else {
        score += (residual_f - mean_residual) * 0.5;
    }

    // Dead-space ratio and quadratic refinement.
    score += (1.0 - post_residual as f64 / cap) * 14.0 * progress;
    if waste_frac > 0.6 {
        score += (waste_frac - 0.6) * (90.0 + 40.0 * progress);
    }

    // Last-chance bonus: sole fitting bin strongly favored over a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Reusable sweet-spot residuals matched to upcoming demand.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr >= 20.0 && pr <= 60.0 {
            let reusable = if next_item_size > 0 && (next_item_size as f64) <= pr { 1.5 } else { 1.0 };
            score -= 22.0 * (1.0 - progress) * reusable;
        }
        if (pr - cap * 0.5).abs() < cap * 0.08 {
            score -= 40.0;
        }
    }

    // Keep tight bins for tight fits when alternatives exist.
    if bin_residual <= 12 && post_residual > 0 && fitting_bins_count > 1 && item_size < bin_residual {
        score += 55.0 * (1.0 - 0.5 * progress);
    }

    // Modular reuse of common small item sizes.
    if post_residual > 0 && post_residual <= 30 {
        let pr = post_residual as f64;
        let mod_bonus = if post_residual % 10 == 0 {
            60.0
        } else if post_residual % 5 == 0 {
            40.0
        } else {
            0.0
        };
        score -= mod_bonus * (0.6 + 0.4 * (1.0 - progress)) * (1.0 - pr / 60.0).max(0.5);
    }

    // Near-miss dead space penalty.
    if next_item_size > post_residual && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8.0 {
            score += (8.0 - gap) * 30.0 * (1.2 - progress);
        }
    }

    // Two-step chain bonus.
    if next_item_size > 0 && next_item_size < post_residual {
        let chain_left = post_residual - next_item_size;
        if chain_left >= 10 {
            score -= 45.0 * (1.0 - 0.5 * progress);
        }
    }

    // Late-stream consolidation: drain largest residuals to close bins.
    if progress > 0.85 && post_residual > 0 {
        let drain = (post_residual as f64 / cap) * (progress - 0.85) * 400.0;
        score -= drain;
    }

    // Slivers below 8 late in the stream are nearly always waste.
    if post_residual > 0 && post_residual < 8 && progress > 0.5 {
        score += 60.0 * (progress - 0.5) * 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 10000.0;
        } else if next_item_size > 0
            && next_item_size > post_residual
            && item_size >= bin_capacity / 2
            && open_bins_count >= 2
        {
            score -= 160.0;
        }
        if progress > 0.72 && fitting_bins_count > 0 && post_residual < item_size {
            score -= 60.0 * progress;
        }
        if progress > 0.4 && progress <= 0.72 && item_size as f64 > mean_residual * 1.5 {
            score -= 35.0;
        }
        if next_item_size > 0
            && next_item_size > post_residual
            && next_item_size <= bin_capacity
            && fitting_bins_count <= 2
        {
            score -= 50.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && waste_frac > 0.75 && item_size as f64 > mean_residual {
            score -= 45.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 3 && waste_frac > 0.65 {
            score -= 70.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let near_fit_gap = (item_size as f64 - mean_residual).abs();
            if near_fit_gap < cap * 0.05 {
                score += 30.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count > 0 && post_residual <= 4 {
            score += 120.0 * (1.0 - 0.4 * progress);
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 90.0 * (progress - 0.8) * 5.0;
        }
        // Mid-stream, resist new bins when mean residual across open
        // bins could still absorb the item — reuse scattered space first.
        if progress > 0.35 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0 * (progress - 0.35) * 3.0;
        }
        // Resist new bins when the best post-residual among open bins
        // leaves a chain-compatible leftover (>= 10) for the next item.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score += 55.0 * (1.0 - progress);
            }
        }
        // Early stream, allow new bins for very large items that would
        // otherwise strand a small residual in an existing bin.
        if progress < 0.3 && item_size as f64 > cap * 0.7 && fitting_bins_count > 0 {
            score -= 25.0 * (0.3 - progress) * 10.0;
        }
        // Strong mid-stream resistance to new bins whenever the item
        // is small relative to capacity — scattered space usually suffices.
        if progress > 0.25 && progress < 0.75 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            score += 35.0 * (1.0 - (progress - 0.25).abs() / 0.5);
        }
        // Opening a new bin is only attractive if the residual it
        // leaves (cap - item) is itself likely reusable by the next item.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let new_res = cap - item_size as f64;
            if new_res > 0.0 && (next_item_size as f64) <= new_res {
                score -= 30.0 * (1.0 - progress);
            }
        }
        // MUTATION: penalize new bins whose leftover residual falls into
        // the "dead zone" — too small to be reusable by typical items
        // (common small sizes cluster under 30 in most streams).
        if fitting_bins_count > 0 {
            let new_res = cap - item_size as f64;
            if new_res > 0.0 && new_res < 30.0 {
                score += (30.0 - new_res) * 3.0 * (1.0 - progress);
            }
        }
        // MUTATION: mid-stream, if the item would leave a large open-bin
        // residual stranded, prefer the fresh bin whose leftover is large
        // and reusable (cap - item >= 40).
        if progress > 0.3 && progress < 0.8 && fitting_bins_count > 0 {
            let new_res = cap - item_size as f64;
            if new_res >= 40.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream
        // so scattered space is consumed before fresh bins open.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when the
        // item is small and many bins fit it — keeps small residuals intact.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // Reward bins whose post-residual exactly matches a plausible
        // upcoming demand bucket (multiples of 5/10) — sharper residual targeting.
        if post_residual > 0 && post_residual <= 50 && (post_residual % 5 == 0) {
            score -= 18.0 * (1.0 - progress);
        }
        // Penalize leaving residuals just below the next item's size
        // (dead space that cannot serve the immediate future).
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
        // MUTATION: best-fit pressure — among fitting bins, reward tighter
        // post-residuals proportionally, scaled by how many alternatives
        // exist, to sharpen compaction beyond exact-match tiers.
        if post_residual > 0 {
            let tightness = 1.0 - post_residual as f64 / residual_f.max(1.0);
            score -= tightness * 25.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION: late-stream, strongly prefer bins whose post-residual
        // is zero or tiny so bins actually close instead of lingering.
        if progress > 0.7 && post_residual > 0 && post_residual < 5 {
            score += 35.0 * (progress - 0.7) * 3.0;
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residual values that are too small
    // to be useful for future items (items >= 1, but small gaps < ~10 are near-dead).
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead-space penalty grows sharply as gap shrinks below usable threshold.
        let dead_threshold = 10.0_f64.min(pr);
        score += (10.0 - dead_threshold) * 8.0;
        // Nonlinear penalty: small gaps are quadratic-bad.
        score += (10.0 - pr.min(10.0)).powi(2) * 0.5;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size (low waste ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: penalize opening/using many bins; encourage consolidating.
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive if no good fit exists or residual
        // of existing bins is too fragmented to hold item + lookahead.
        let need = item_size as f64 + next_item_size as f64;
        let fragmented = mean_residual < need * 0.9 && next_item_size > 0;
        if fragmented || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // Prefer reusing open bins when they fit well.
            score += 30.0 + 3.0 * open_bins_count as f64;
        }
    } else {
        // Using an existing bin relieves pressure slightly with fewer open bins.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward proportional to headroom.
        score -= 5.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        // Post residual can't hold the next item: penalize dead space.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * (mean_residual / bin_capacity as f64 - 0.5).abs();

    score
}

