pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: bin residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still hold the next item: mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.15;
    }

    // Dead space: post-residual too small for next item (or nothing left usable).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfectly closed bin is great
    }

    // Penalize leaving residual far below mean residual (creating outlier dead space).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
