        // Soften resistance when the next item is large and no open bin could
        // ever hold it after this placement.
        if next_item_size > 0
            && next_item_size as f64 > mean_residual
            && next_item_size as f64 > cap * 0.55
            && fitting_bins_count > 0
        {
            score -= 30.0 * (1.0 - progress);
        }
        // Strong resistance when item is large relative to mean residual.
        if fitting_bins_count > 0 && item_size as f64 > mean_residual * 2.0 {
            score -= 20.0;
        }
        // Hard late-stream gate — after 60% progress, only open a new bin if no
        // existing bin can hold the item at all.
        if progress > 0.6 && fitting_bins_count > 0 {
            score += 400.0 * (progress - 0.6);
        }
        // New-bin lookahead gate — if the next item is small enough to fit
        // comfortably in the residual of some existing bin after this item,
        // strongly resist opening a fresh bin.
        if fitting_bins_count > 0
            && next_item_size > 0
            && next_item_size as f64 <= mean_residual * 0.9
            && item_size as f64 > mean_residual * 1.2
        {
            score += 70.0 * (0.5 + 0.5 * progress);
        }
        // COMBINED: strong mid-stream resistance to new bins whenever the item
        // is small relative to capacity — scattered space usually suffices.
        if progress > 0.25 && progress < 0.75 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            score += 35.0 * (1.0 - (progress - 0.25).abs() / 0.5);
        }
        // COMBINED: opening a new bin is only attractive if the residual it
        // leaves (cap - item) is itself likely reusable by the next item.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let new_res = cap - item_size as f64;
            if new_res > 0.0 && (next_item_size as f64) <= new_res {
                score -= 30.0 * (1.0 - progress);
            }
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when the item is small.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // Reward bins whose residual is just above the item size — minimal
        // overhang means minimal stranded space.
        if bin_residual > item_size {
            let overhang = (bin_residual - item_size) as f64;
            score -= (18.0 - overhang.min(18.0)) * 2.2 * (0.5 + 0.5 * progress);
        }
        // Overhang-aware chain reward — a placement whose leftover overhang
        // exactly matches the next item's size class compounds value.
        if bin_residual > item_size && next_item_size > 0 {
            let overhang = bin_residual - item_size;
            if overhang as u64 + post_residual as u64 >= next_item_size as u64
                && (overhang as u64 + post_residual as u64 - next_item_size as u64) <= 6
            {
                score -= 40.0 * (1.0 - 0.4 * progress);
            }
        }
        // COMBINED: reward post-residuals matching plausible demand buckets
        // (multiples of 5) — sharper residual targeting for future fits.
        if post_residual > 0 && post_residual <= 50 && post_residual % 5 == 0 {
            score -= 18.0 * (1.0 - progress);
        }
        // COMBINED: penalize leaving residuals just below the next item's size
        // (dead space that cannot serve the immediate future).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 25 (quarter-capacity classes)
    let q = post_residual / 25;
    let r = post_residual % 25;

    // Reward post_residuals in "usable" classes: large leftovers that can host
    // typical mid-size items (>= 25) are worth keeping; tiny slivers are dead space.
    match q {
        0 => score += 12.0,                       // 0..24: near-dead space penalty
        1 => score -= 6.0,                        // 25..49: hosts small items
        2 => score -= 10.0,                       // 50..74: hosts medium items
        _ => score -= 14.0,                       // 75..99: very usable
    }
    // Fine-tune within class: lower residual within a class = tighter fit = better
    score += r as f64 * 0.15;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;                        // perfect chain: item + next fills bin
        } else if slack < 25 {
            score -= 8.0;                         // next leaves small but acceptable waste
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize more if we are leaving a sliver
        if post_residual > 0 && post_residual < 25 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding: many open bins with high mean residual -> prefer consolidating here
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > (bin_capacity as f64) * 0.5 {
        score -= 3.0 + progress * 3.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): must be chosen only when
    // no open bin offers a decent fit. Penalize it moderately so it wins only
    // when all open bins are tight/dead-space traps.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.1;
        // late in the stream, opening a fresh bin is relatively cheaper
        score -= progress * 5.0;
    }

    // Exact-fit reward: filling the bin completely is always ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

