            let left = post_residual - next_item_size;
            if left <= 6 {
                score += 90.0 * (1.0 - progress);
            }
        }
        // MUTATION: new bins are more tolerable when the leftover they create
        // is large and matches common item-size buckets (likely reusable later).
        let new_left = cap - item_size as f64;
        if fitting_bins_count > 0 && new_left >= 40.0 && (new_left as u32) % 10 == 0 {
            score -= 25.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream
        // so scattered space is consumed before fresh bins open.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when the
        // item is small and many bins fit it — keeps small residuals intact.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // Reward bins whose post-residual exactly matches a plausible
        // upcoming demand bucket (multiples of 5/10) — sharper residual targeting.
        if post_residual > 0 && post_residual <= 50 && (post_residual % 5 == 0) {
            score -= 18.0 * (1.0 - progress);
        }
        // Penalize leaving residuals just below the next item's size
        // (dead space that cannot serve the immediate future).
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
        // MUTATION: dead-space-ratio fix — penalize bins whose post-residual
        // is a stranded sliver relative to the next item even when the gap is
        // moderate (up to 12), scaled by how few alternatives exist.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let gap = (next_item_size - post_residual) as f64;
            if gap > 4.0 && gap <= 12.0 {
                score += gap * 4.0 * (1.0 - progress) * (1.0 + 0.5 / (fitting_bins_count.max(1) as f64));
            }
        }
        // MUTATION: prefer consuming the largest residuals when the item leaves
        // a tight post-residual — reduces dead-space accumulation across bins.
        if post_residual > 0 && post_residual <= 15 && residual_f > mean_residual {
            score -= 20.0 * (1.0 - progress) * (residual_f - mean_residual) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are toxic.
    // Treat post_residual in [1, 10] as near-dead (hard floor of item sizes), and
    // [11, 25] as risky dead space depending on stream position.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual <= 10 {
        score += 90.0 * (1.0 - pr / 10.0); // unusable sliver: heavy penalty
    } else if post_residual <= 25 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - (pr - 10.0) / 15.0) * (0.5 + 0.5 * progress);
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many bins open, prefer consolidating into existing ones
    // rather than spreading; discourage new bins when open count is already high.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate; allow it when
        // the item is huge and would leave a clean residual elsewhere anyway.
        score += 30.0 + 12.0 * open_pressure;
        if item_size >= 80 {
            score -= 35.0;
        }
    } else {
        score -= 5.0 * open_pressure;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement
    // (chains items nicely); if next item would need exactly this bin's current residual
    // but we consume it, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 18.0 * (nx / 100.0);
        }
        if nx > bin_residual as f64 {
            // next item won't fit here anyway; no conflict, mild consolidation reward
            score -= 4.0;
        }
    }

    // Prefer bins below mean residual (fill the emptier ones less; keep big spaces big).
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
