            score += 120.0 * (1.0 - 0.4 * progress);
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 90.0 * (progress - 0.8) * 5.0;
        }
        // Resist new bins when mean residual across open bins could absorb the item.
        if progress > 0.35 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0 * (progress - 0.35) * 3.0;
        }
        // Resist new bins when the best post-residual leaves a chain-compatible
        // leftover (>= 10) for the next item.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score += 55.0 * (1.0 - progress);
            }
        }
        // Early stream, allow new bins for very large items.
        if progress < 0.3 && item_size as f64 > cap * 0.7 && fitting_bins_count > 0 {
            score -= 25.0 * (0.3 - progress) * 10.0;
        }
        // Soften resistance when the next item is large and no open bin could
        // ever hold it after this placement.
        if next_item_size > 0
            && next_item_size as f64 > mean_residual
            && next_item_size as f64 > cap * 0.55
            && fitting_bins_count > 0
        {
            score -= 30.0 * (1.0 - progress);
        }
        // Strong resistance when item is large relative to mean residual.
        if fitting_bins_count > 0 && item_size as f64 > mean_residual * 2.0 {
            score -= 20.0;
        }
        // Hard late-stream gate — after 60% progress, only open a new bin if no
        // existing bin can hold the item at all.
        if progress > 0.6 && fitting_bins_count > 0 {
            score += 400.0 * (progress - 0.6);
        }
        // New-bin lookahead gate — if the next item is small enough to
        // fit comfortably in the residual of some existing bin after this item,
        // strongly resist opening a fresh bin.
        if fitting_bins_count > 0
            && next_item_size > 0
            && next_item_size as f64 <= mean_residual * 0.9
            && item_size as f64 > mean_residual * 1.2
        {
            score += 70.0 * (0.5 + 0.5 * progress);
        }
        // MUTATION: mid-stream resistance to new bins for small items —
        // scattered space usually suffices; peak resistance mid-stream.
        if progress > 0.25 && progress < 0.75 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            score += 40.0 * (1.0 - (progress - 0.25).abs() / 0.5);
        }
        // MUTATION: only open a new bin if its own residual (cap - item) is
        // likely reusable by the next item; otherwise resist.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let new_res = cap - item_size as f64;
            if new_res > 0.0 && (next_item_size as f64) <= new_res {
                score -= 35.0 * (1.0 - progress);
            } else if new_res > 0.0 && (next_item_size as f64) > new_res {
                score += 25.0 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: resist new bins when the item fits an existing bin whose
        // residual is near the item size (tight overhang placement available).
        if fitting_bins_count > 0 && item_size as f64 >= mean_residual * 0.8 {
            score += 20.0 * (1.0 - progress);
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Extra compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when the item is small.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // Reward bins whose residual is just above the item size — minimal
        // overhang means minimal stranded space.
        if bin_residual > item_size {
            let overhang = (bin_residual - item_size) as f64;
            score -= (18.0 - overhang.min(18.0)) * 2.2 * (0.5 + 0.5 * progress);
        }
        // Overhang-aware chain reward — leftover overhang compounds with the
        // next item's demand class.
        if bin_residual > item_size && next_item_size > 0 {
            let overhang = bin_residual - item_size;
            if overhang as u64 + post_residual as u64 >= next_item_size as u64
                && (overhang as u64 + post_residual as u64 - next_item_size as u64) <= 6
            {
                score -= 40.0 * (1.0 - 0.4 * progress);
            }
        }
        // MUTATION: reward post-residuals matching plausible demand buckets
        // (multiples of 5) — sharper residual targeting.
        if post_residual > 0 && post_residual <= 50 && (post_residual % 5 == 0) {
            score -= 18.0 * (1.0 - progress);
        }
        // MUTATION: penalize residuals just below the next item's size —
        // dead space that cannot serve the immediate future.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items can use.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        // Dead space is worse late in the stream when fewer chances remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * dead * (0.4 + 0.6 * progress);
    }

    // Lookahead: strongly reward bins whose post-residual still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // Extra bonus if next item fills it exactly (perfect chain).
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Penalize creating residual too small for the known next item.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer fuller bins on average relative to fleet state.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.15 * rel;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper early when few bins exist.
        let early = 1.0 - (step_index as f64 / total_items.max(1) as f64).min(1.0);
        score += 12.0 + 25.0 * (1.0 - early) + 0.5 * open_bins_count as f64;
        // But if the item is huge relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild penalty for very large items into very full bins (fragmentation risk).
    if item_size > 50 && post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
