        }
        if fitting_bins_count > 0 && post_residual <= 4 {
            nb += 120.0 * (1.0 - 0.4 * progress);
        }
        if progress > 0.8 && fitting_bins_count > 0 {
            nb += 90.0 * (progress - 0.8) * 5.0;
        }
        // Mid-stream resistance when scattered mean residual could absorb item.
        if progress > 0.35 && mean_residual >= item_size as f64 {
            nb += 40.0 * (progress - 0.35) * 3.0;
        }
        // Chain-compatible leftover exists in an existing bin.
        if next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                nb += 55.0 * (1.0 - progress);
            }
        }
        // Early stream, allow new bins for very large items.
        if progress < 0.3 && item_size as f64 > cap * 0.7 && fitting_bins_count > 0 {
            nb -= 25.0 * (0.3 - progress) * 10.0;
        }
        // Many fitting bins = low fragmentation pressure; resist new bins.
        if fitting_bins_count >= 4 {
