        // space usually suffices, so keep bin count down.
        if progress > 0.25 && progress < 0.75 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            nb += 35.0 * (1.0 - (progress - 0.25).abs() / 0.5);
        }
