        // reusable by the next item.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let new_res = cap - item_size as f64;
            if new_res > 0.0 && (next_item_size as f64) <= new_res {
                nb -= 30.0 * (1.0 - progress);
            } else {
                nb += 20.0 * (1.0 - progress);
            }
        }
        score += nb;
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first when item is small.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // Chain compaction: post-residual exactly matches next item.
        if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
            score -= 40.0 * (1.0 - 0.3 * progress);
        }
        // MUTATION: penalize residuals just below next item's size (dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
        // MUTATION: reward residuals matching plausible demand buckets.
        if post_residual > 0 && post_residual <= 50 && post_residual % 5 == 0 {
            score -= 18.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr + 3.0 * progress * progress * norm_pr * norm_pr);

    let mut score = poly * cap;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - (pr / cap);
    score -= fit_quality * fit_quality * 30.0;

    // Last-chance bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

