        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill class is best
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class the residual into harmonic buckets: tiny / small / medium / large
        let cls = match post_residual {
            0..=5 => 0,        // dead space class
            6..=15 => 1,       // hard-to-fill
            16..=30 => 2,      // moderate
            31..=60 => 3,      // useful
            _ => 4,            // large residual
        };
        score += cls as f64 * 12.0;

        // Dead-space penalty: residuals that no typical item (>=10) can use
        if post_residual < 10 {
            score += 200.0;
        }

        // Modulo-10 coupling: residuals divisible by 10 pair well with the
        // integer item sizes common in streams
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }

        // Integer-division threshold: can next item fit here?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 15.0;
                // Perfect two-step closure: item + next exactly fills bin
                if next_item_size == post_residual {
                    score -= 60.0;
                }
            } else {
                score += 10.0;
            }
        } else {
            // Last item: prefer exact fill, otherwise minimize waste
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling bins when many are open (bin consolidation pressure)
    score -= (open_bins_count as f64) * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 2.0;

    // Early stream: slight preference for compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and residual would remain highly usable
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 50 {
            score -= 45.0;
        }
    }

    // Deviation from mean residual: prefer bins already below-average residual
    // (i.e., fuller bins) to concentrate waste
    score += (mean_residual - post_residual as f64) * -0.3;

    score
}

