        }
        if fitting_bins_count > 0 && next_item_size as f64 > cap * 0.5 && (cap - item_size as f64) < next_item_size as f64 {
            score += 30.0 * (0.5 + 0.5 * progress);
        }
        // MUTATION: new-bin leftover should ideally land on a reusable
        // bucket (multiple of 5 or 10) that future items can fill exactly;
        // penalize awkward leftovers in (16, 30) that are hard to consume.
        if fitting_bins_count > 0 && new_res2 >= 16.0 && new_res2 <= 30.0 {
            let bucket_hit = new_res2 as u32 % 5 == 0;
            if bucket_hit {
                score -= 20.0 * (1.0 - progress);
            } else {
