            let demand_bucket = ((next_item_size + 5) / 10 * 10) as i64;
            let diff = (post_residual as i64 - demand_bucket).abs();
            if diff <= 3 {
                score -= 30.0 * (1.0 - progress);
            }
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
