        }
        // MUTATION: if the new bin's leftover would exactly match the next
        // item, opening is genuinely good — reward it to beat mediocre fits.
        if fitting_bins_count > 0 && next_item_size > 0 && (cap as u32 - item_size) == next_item_size {
