        if next_item_size > 0 && (item_size as u64) + (next_item_size as u64) <= bin_residual as u64 {
            let mut squeeze = 70.0 * (1.0 - 0.4 * progress);
            let after = bin_residual - item_size - next_item_size;
            if after <= 4 {
                squeeze += 55.0;
            } else if after <= 10 {
