        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 8 && post_residual - next_item_size > 0 {
            score -= 35.0 * (1.0 - (post_residual - next_item_size) as f64 / 9.0);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

