        // fitting bins mid/late stream to close bins.
        if progress > 0.4 && post_residual >= 15 && residual_f >= cap * 0.55 {
            score -= 20.0 * (progress - 0.4);
        }
        // Exact-fill steering — perfect chain with the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 90.0;
        }
        // Near-closure pressure — tiny post-residual gets an escalating bonus.
        if post_residual > 0 && post_residual <= 6 {
            score -= 45.0 * (1.0 - post_residual as f64 / 7.0) * (0.6 + 0.8 * progress);
        }
        // Two-item squeeze — both current and next item fit in residual.
        if next_item_size > 0 && (item_size as u64) + (next_item_size as u64) <= bin_residual as u64 {
            score -= 70.0 * (1.0 - 0.4 * progress);
        }
        // MUTATION: residual-band targeting — when the post-residual lands
        // within a small window of the next item size plus a common small
        // item (10/20/25), the bin can absorb two more items; reward it so
        // multi-step chains get built instead of one-step fits.
        if next_item_size > 0 && post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 10 || after_next == 20 || after_next == 25 {
                score -= 30.0 * (1.0 - 0.5 * progress);
            }
        }
        // MUTATION: near-exact chain sharpening — post-residual within 1-2
        // of the next item is nearly as good as an exact match; give it a
        // graded bonus rather than falling through to the generic tiers.
        if next_item_size > 0 && post_residual > next_item_size {
            let diff = post_residual - next_item_size;
            if diff <= 2 {
                score -= (60.0 - 15.0 * diff as f64) * (0.7 + 0.5 * progress);
            }
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
