            score -= 70.0 * (1.0 - 0.4 * progress);
        }
        // MUTATION: closure countdown — when only a few items remain and
        // this placement nearly empties the bin, push hard to finish it
        // so no scattered sliver survives to the end of the stream.
        if remaining <= 12.0 && post_residual > 0 && post_residual < 15 {
            score -= 70.0 * (1.0 - post_residual as f64 / 15.0);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

