        }
        if next_item_size > 0 && (item_size as u64) + (next_item_size as u64) <= bin_residual as u64 {
            score -= 70.0 * (1.0 - 0.4 * progress);
        }
        // MUTATION: triple-fill anticipation — reward bins that could
        // absorb the next two items' worth of demand, steering multi-item
        // compaction into single bins.
