    // Lookahead coupling: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.35;
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item chain
        }
        // Penalize residuals next item cannot use at all.
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer using bins with larger residuals when many bins are open (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Mild pressure to close out bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // New-bin candidate: make it attractive only when no open bin fits well
    // or when open-bin residuals are all poor fits for the item.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let high_fragmentation = if open_bins_count > 6 && mean_residual < 35.0 { 1.0 } else { 0.0 };
        score += 20.0;                 // default cost of a fresh bin
        score -= poor_fits * 60.0;     // no bin fits -> open new bin
