        // absorb the next two items' worth of demand, steering multi-item
        // compaction into single bins.
        if next_item_size > 0 && (item_size as u64) + 2 * (next_item_size as u64) <= bin_residual as u64 {
            score -= 30.0 * (1.0 - progress);
        }
        // MUTATION: harmonic residual targeting — reward mid-band
        // post-residuals (25..45) when the next item fits twice within,
        // enabling clean second placements.
        if post_residual >= 25 && post_residual <= 45 && next_item_size > 0 && (next_item_size as u64) * 2 <= post_residual as u64 {
            score -= 26.0 * (0.5 + 0.5 * (1.0 - progress));
        }
        // MUTATION: bin-closure race — when this placement nearly empties
        // the bin, escalate pressure so half-full bins get finished off.
        if post_residual > 0 && post_residual <= item_size && residual_f > cap * 0.4 {
            score -= 18.0 * (1.0 - post_residual as f64 / item_size.max(1) as f64) * (0.4 + 0.9 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual bucketed by integer division thresholds.
    // Small post_residual = tight fit = reward heavily.
    let tight_class = post_residual / 10; // classes 0..=10
    match tight_class {
        0 => score -= 60.0,                 // near-perfect fit (0..10 dead space)
        1 => score -= 35.0,                 // excellent fit
        2 => score -= 18.0,                 // good fit
        3 => score -= 8.0,                  // decent
        4 => score -= 2.0,                  // ok
        _ => {}                              // poor fits: raw post_residual penalty dominates
    }

    // Modulo arithmetic on post_residual: residues that pair well with common
    // small items (multiples of 5/10) are more reusable.
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0;                        // round residual: highly reusable
    } else if r <= 3 {
        score += 4.0;                        // awkward sliver residue
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 25.0;               // next item lands near-perfectly here
            } else if slack <= 30 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item cannot fit here; penalize more if it's a big miss
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual > 40 {
            score += 10.0;                   // but a very loose fit is still bad
        }
    }

    // New-bin candidate handling: empty bin should only win when the current
    // item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin for large items late in stream with many bins open
        let large_item = item_size > 60;
        let many_open = open_bins_count as f64 > 4.0;
        if large_item && many_open {
            score -= 15.0 * progress;
        } else {
            score += 45.0;                   // default: discourage opening new bins
        }
    }

    // Mild mean-residual coupling: placing into a bin far from the mean
    // residual balances the pool.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight time pressure: late in stream, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

