        if next_item_size > 0 && (item_size as u64) + (next_item_size as u64) <= bin_residual as u64 {
            score -= 70.0 * (1.0 - 0.4 * progress);
        }
        // MUTATION (gen 46): residual-efficiency scaling — when the
        // placement leaves a post-residual that is a large share of the
        // bin residual (poor utilization of this bin's space), apply a
