            let util = 1.0 - post_residual as f64 / bin_residual as f64;
            if util < 0.5 {
                score += (0.5 - util) * 60.0 * (0.4 + 0.6 * progress);
            } else if util > 0.85 {
                score -= (util - 0.85) * 80.0 * (0.5 + 0.5 * progress);
            }
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1..10)
    // are worthless dead space. Penalize heavily when post_residual falls into
    // the "unusable gap" band (1..=9), scaled by how deep the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Also penalize gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.25 * next_item_size as f64;
    }

    // Reward tight fits (small post_residual) beyond raw value.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress) * 0.5;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid wasting the residual here).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: opening a fresh bin should be discouraged unless the
    // current placement would create severe dead space. Base penalty plus a
    // discount when the item is large relative to capacity (fresh bin useful).
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        if post_residual < 10 && post_residual > 0 {
            penalty -= 70.0; // allow new bin when this bin would be a fresh dead gap
        }
        if item_size >= 50 {
            penalty += 10.0; // large items pack fine anywhere; prefer existing bins
        }
        score += penalty;
    }

    // Mild preference for bins below mean residual (reduces variance of gaps).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

