            && fitting_bins_count <= 2
        {
            score -= 60.0 * (1.0 - progress);
        }
        if fitting_bins_count > 0 && waste_frac > 0.75 && item_size as f64 > mean_residual {
            score -= 55.0 * (1.0 - progress);
        }
        // Many-fit gate: several alternatives make a fresh bin clearly worse.
        if fitting_bins_count >= 3 && waste_frac > 0.65 {
            score -= 75.0 * (0.4 + 0.6 * (1.0 - progress));
        }
        // Near-fit trap: item almost matches mean residual — existing bins fit better.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let near_fit_gap = (item_size as f64 - mean_residual).abs();
            if near_fit_gap < cap * 0.05 {
                score += 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0
            && open_bins_count > 0
            && (mean_residual * open_bins_count as f64) < (next_item_size as f64) * 1.2
        {
            score -= 45.0;
        }
        // Resist new bins when mean residual could still absorb the item.
        if progress > 0.35 && fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 40.0 * (progress - 0.35) * 3.0;
        }
        // Resist when open-bin leftover leaves a chain-compatible remainder.
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left >= 10 {
                score += 55.0 * (1.0 - progress);
            }
        }
        // Early stream: allow new bins for very large items.
        if progress < 0.3 && item_size as f64 > cap * 0.7 && fitting_bins_count > 0 {
            score -= 25.0 * (0.3 - progress) * 10.0;
        }
        // Strong mid-stream resistance for small items.
        if progress > 0.25 && progress < 0.75 && fitting_bins_count > 0 && (item_size as f64) < cap * 0.45 {
            score += 35.0 * (1.0 - (progress - 0.25).abs() / 0.5);
        }
        // Hard mid-stream gate: several fits and healthy mean residual.
        if progress > 0.3 && progress < 0.9 && fitting_bins_count >= 2 && (mean_residual * 2.0) >= item_size as f64 {
            score += 55.0 * (1.0 - (progress - 0.3).abs() / 0.6).max(0.0);
        }
        // New-bin residual quality gate: leftover sliver is bad.
        let new_res = cap - item_size as f64;
        if fitting_bins_count > 0 && new_res > 0.0 && new_res < 10.0 {
            score += 95.0 * (1.0 - progress);
        }
        // Extended sliver gate: awkward 10..16 band late in the stream.
        if fitting_bins_count > 0 && new_res >= 10.0 && new_res < 16.0 && progress > 0.55 {
            score += 35.0 * (progress - 0.55);
        }
        // Pair-anticipation: large next item the new leftover can't hold.
        if fitting_bins_count > 0 && next_item_size as f64 > cap * 0.5 && new_res < next_item_size as f64 {
            score += 30.0 * (0.5 + 0.5 * progress);
        }
        // Opening is attractive only if the leftover serves the next item.
        if fitting_bins_count > 0 && next_item_size > 0 && new_res > 0.0 && (next_item_size as f64) <= new_res {
            score -= 30.0 * (1.0 - progress);
        }
        // Resist new bins when a tight fit is available (post_residual <= 4).
        if fitting_bins_count > 0 && post_residual <= 4 {
            score += 125.0 * (1.0 - 0.4 * progress);
        }
        // Late-stream hard resistance to new bins.
        if progress > 0.8 && fitting_bins_count > 0 {
            score += 95.0 * (progress - 0.8) * 5.0;
        }
        // Dead-space ratio coupling — a new bin whose leftover fraction
        // exceeds the current mean waste is extra wasteful.
        if fitting_bins_count > 0 && new_res / cap > waste_frac.max(0.2) {
            score += 25.0 * (new_res / cap - waste_frac.max(0.2)) * (0.5 + progress);
        }
        // MUTATION: new-bin lookahead squeeze — opening a fresh bin is only
        // justified if the current item plus the next item cannot both be
        // served by the existing scattered space; when mean residual across
        // open bins covers item+next, opening is clearly premature.
        if fitting_bins_count > 0
            && next_item_size > 0
            && (item_size as f64 + next_item_size as f64) <= mean_residual * open_bins_count as f64
            && progress > 0.2
        {
            score += 65.0 * (1.0 - 0.5 * progress);
        }
    } else {
        if post_residual > 8 && post_residual < 20 && fitting_bins_count > 1 {
            score += 25.0;
        }
        if residual_f > mean_residual * 1.6 && post_residual > 0 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Compaction pressure on large-residual bins mid-stream.
        if residual_f > mean_residual * 1.3 && progress > 0.3 && post_residual >= 10 {
            score -= 12.0 * progress;
        }
        // Prefer filling bins with larger residuals first for small items.
        if item_size <= 20 && fitting_bins_count > 2 && residual_f > cap * 0.5 {
            score -= 15.0 * (residual_f / cap);
        }
        // Reward residuals on plausible demand buckets (multiples of 5).
        if post_residual > 0 && post_residual <= 50 && post_residual % 5 == 0 {
            score -= 18.0 * (1.0 - progress);
        }
        // Penalize residuals just below the next item's size.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (next_item_size - post_residual) <= 4 {
            score += 40.0 * (1.0 - progress);
        }
        // Compaction bonus on the largest residuals mid/late stream.
        if progress > 0.4 && post_residual >= 15 && residual_f >= cap * 0.55 {
            score -= 20.0 * (progress - 0.4);
        }
        // Exact-fill steering toward the next item's size.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 90.0;
        }
        // Near-closure pressure on tiny post-residuals.
        if post_residual > 0 && post_residual <= 6 {
            score -= 45.0 * (1.0 - post_residual as f64 / 7.0) * (0.6 + 0.8 * progress);
        }
        // Two-item squeeze: current + next both fit this bin's residual.
        if next_item_size > 0 && (item_size as u64) + (next_item_size as u64) <= bin_residual as u64 {
            score -= 70.0 * (1.0 - 0.4 * progress);
        }
        // Three-item squeeze anticipation — a bin whose residual can hold
        // the current item plus two typical small items is a prime
        // compaction target; prefer it over spreading.
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual > 0 {
            let two_more = item_size as u64 + (next_item_size as u64) + (next_item_size as u64).min(20);
            if (two_more as f64) <= bin_residual as f64 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        // Fill-efficiency coupling — reward placements whose fill fraction
        // (1 - waste_frac) is high, scaled by stream depth.
        if waste_frac < 0.35 {
            score -= (0.35 - waste_frac) * 60.0 * (0.4 + 0.6 * progress);
        }
        // MUTATION: residual-consumption depth coupling — when the item
        // consumes most of the bin's residual (>= 70%) but leaves a
        // reusable remainder that the next item can still chain into,
        // this is the ideal compaction; reward it beyond the base tiers.
        if post_residual > 0
            && next_item_size > 0
            && (next_item_size as f64) <= post_residual as f64
            && (item_size as f64) >= residual_f * 0.7
        {
            score -= 35.0 * (0.5 + 0.5 * progress);
        }
    }

    // Mild penalty for spreading across too many open bins, tapering late.
    score += open_bins_count as f64 * (0.5 - 0.25 * progress);

    score
}
